// familyReducer is the sealed semantic half of one invocation. It holds the
// carriers this row's fold is indexed by, and its type is the family's, so the
// call below is a static direct call rather than an interface dispatch.
//
// It also carries the state the declared judgment is issued by. That state is
// the family's, sealed once from the axis schemas the declaration names, so a
// fold resting on cold owner knowledge still takes only carriers as arguments.
type familyReducer struct {
	state     callsite.Judgment
	candidate factor.MountedCall
}

// Reduce is the one irreducible typed judgment of this exact family. The
// execution worker authenticates presence before calling it, so absence never
// becomes a default fact and the fold receives only declared carriers.
func (fold familyReducer) Reduce(cell call.Value) (factor.Value, structure.ReductionOutcome) {
	return fold.state.Effect(fold.candidate, cell)
}

// familyRow is the sealed static half of one plan row: the candidate its fold
// is indexed by and every primitive the installer sealed through the plane.
type familyRow struct {
	candidate   factor.MountedCall
	read0       execution.ExactRead[call.DenseCoordinate, call.Value]
	read0Policy execution.ReadCellPolicy[call.Value]
	write       execution.ExactWrite[owner.DenseCoordinate, factor.Value]
}

// sealedFamily is this rule's whole installed family: one row per plan row and
// the sealed state every invocation reads. Nothing here is mutated after the
// installer returns.
type sealedFamily struct {
	rows  []familyRow
	state callsite.Judgment
}

func (sealed *sealedFamily) NewExecutor(run *execution.Run) execution.Executor {
	if sealed == nil || run == nil {
		return nil
	}
	return &familyWorker{family: sealed, run: run}
}

func (*sealedFamily) InputCapacity() int  { return 1 }
func (*sealedFamily) OutputCapacity() int { return 1 }

// familyWorker is one epoch's reusable invocation lane. Every scratch lives for
// the worker's lifetime, so a warm invocation opens its cursors and its write
// transaction without allocating.
type familyWorker struct {
	family *sealedFamily
	run    *execution.Run
	read0  execution.Scratch[call.DenseCoordinate, call.Value]
	write  execution.Scratch[owner.DenseCoordinate, factor.Value]
}

// settle submits one non-publishing disposition. Every refusal path in this
// worker ends here, so the ticket is settled exactly once.
func (lane *familyWorker) settle(ticket execution.Ticket, outcome structure.ReductionOutcome) (execution.Result, bool) {
	if !ticket.Submit(outcome) {
		return execution.Result{}, false
	}
	return execution.NewResult(outcome, 0)
}

// Execute consumes the one exact existence fact, applies the typed fold, and
// publishes through the consumer-owned target sealed for this candidate.
func (lane *familyWorker) Execute(frame execution.Frame, ticket execution.Ticket) (execution.Result, bool) {
	if lane == nil || lane.family == nil || lane.run == nil || !frame.Valid(ticket) || !lane.run.Owns(ticket) {
		return execution.Result{}, false
	}
	local, localOK := ticket.LocalOrdinal()
	if !localOK || uint64(local) >= uint64(len(lane.family.rows)) {
		return execution.Result{}, false
	}
	row := lane.family.rows[local]
	switch row.read0.Read(ticket, &lane.read0) {
	case execution.ReadAvailable:
		cell, available := lane.read0.Value()
		present := lane.read0.Present()
		region, regionOK := lane.read0.Region()
		if !row.read0.Close(ticket, &lane.read0) {
			_ = lane.read0.Discard(ticket)
			return lane.settle(ticket, structure.Refuse)
		}
		if !available || !regionOK {
			return lane.settle(ticket, structure.Refuse)
		}
		cell, present = row.read0Policy.Cell(cell, present)
		if !present {
			return lane.settle(ticket, structure.NoCandidate)
		}
		value, outcome := (familyReducer{state: lane.family.state, candidate: row.candidate}).Reduce(cell)
		if outcome != structure.Concrete {
			return lane.settle(ticket, outcome)
		}
		outcome = execution.PublishExact(ticket, row.write, &lane.write, region, value)
		if !ticket.Submit(outcome) {
			return execution.Result{}, false
		}
		written := 0
		if outcome == structure.Concrete {
			written = 1
		}
		return execution.NewResult(outcome, written)
	case execution.ReadExhausted:
		if !row.read0.Close(ticket, &lane.read0) {
			return lane.settle(ticket, structure.Refuse)
		}
		return lane.settle(ticket, structure.NoCandidate)
	default:
		_ = lane.read0.Discard(ticket)
		return lane.settle(ticket, structure.Refuse)
	}
}

// familyInstaller authors this rule's execution family. The axis schemas it
// holds are the ones the declaration names: the candidate directory it resolves
// dense candidates through, and every static axis a declared relation derives
// against. It reaches no owner callback and no runtime capability.
//
// It holds NO rule ordinal. Which rule an installer authors is the claim it
// was installed under, and the family table resolves an installer only for
// that claim; a copy kept here would be a second answer to a question the
// table already answers, and one that goes stale on its own.
type familyInstaller struct {
	effectSchema *factor.Algebra
	callSchema   *call.Algebra
}

// NewFamilyInstaller seals this rule's family installer against the axis schemas
// its declaration names. The bind arm that resolves those schemas from its
// composition's authorities is the owner's own, because how an authority
// record is reached is that composition's knowledge and not this rule's.
func NewFamilyInstaller(effectSchema *factor.Algebra, callSchema *call.Algebra) (execution.RuleFamilyInstaller[owner.DenseCoordinate, factor.Value], bool) {
	install := familyInstaller{effectSchema: effectSchema, callSchema: callSchema}
	if !install.available() {
		return nil, false
	}
	return install, true
}

// available proves every schema this installer seals against was supplied.
// Whether a supplied schema is itself admissible is that schema's own answer,
// given below when a candidate or a projection is resolved through it.
func (install familyInstaller) available() bool {
	return install.effectSchema != nil && install.callSchema != nil
}

func (install familyInstaller) InstallRuleFamily(plane execution.FormPlane[owner.DenseCoordinate, factor.Value], _ uint32, rows []execution.FormRow) (execution.Family, []execution.FormAddress, bool) {
	if !install.available() || !plane.Valid() || len(rows) == 0 {
		return nil, nil, false
	}
	state, stateOK := callsite.DeriveSelected(install.effectSchema, install.callSchema)
	if !stateOK {
		return nil, nil, false
	}
	sealed := &sealedFamily{rows: make([]familyRow, 0, len(rows)), state: state}
	addresses := make([]execution.FormAddress, 0, len(rows))
	for _, planRow := range rows {
		if planRow.Form != execution.FormExact || !planRow.Rule.Available() || planRow.Rule.ReadCount() != 1 || planRow.Rule.OutputCount() != 1 {
			return nil, nil, false
		}
		output, outputOK := planRow.Rule.OutputAt(0)
		if !outputOK || output.Mode != program.ModeExact || output.RouteJoinPresent || output.Slot != 0 {
			return nil, nil, false
		}
		carryMode, carryPresent := planRow.Rule.CarryMode()
		if carryPresent || carryMode != 0 {
			return nil, nil, false
		}
		plan0, plan0OK := planRow.Rule.ReadAt(0)
		if !plan0OK || plan0.Form != program.Exact || plan0.Input != 0 || plan0.PointBound != program.PointBound {
			return nil, nil, false
		}
		candidate, candidateOK := install.effectSchema.MountedCallAt(int(planRow.Candidate))
		if !candidateOK {
			return nil, nil, false
		}
		foreign0, foreign0OK := plane.Foreign(plan0.Factor)
		if !foreign0OK {
			return nil, nil, false
		}
		read0Sealed, read0SealedOK := execution.ForeignRowExactRead[call.DenseCoordinate, call.Value](foreign0, planRow, 0)
		read0Policy, read0PolicyOK := execution.ForeignReadCellPolicy[call.DenseCoordinate, call.Value](foreign0, plan0.Contract)
		if !read0PolicyOK {
			return nil, nil, false
		}
		writeSealed, writeSealedOK := plane.ExactWrite(planRow.Target, uint16(output.Slot))
		if !writeSealedOK || !read0SealedOK {
			return nil, nil, false
		}
		addresses = append(addresses, execution.FormAddress{Member: planRow.Member, Local: uint32(len(sealed.rows))})
		sealed.rows = append(sealed.rows, familyRow{candidate: candidate, read0: read0Sealed, read0Policy: read0Policy, write: writeSealed})
	}
	return sealed, addresses, true
}
